const messages = board.channel(board.MAIN_CHANNEL) || [];
let inputText = "";
for (let i = messages.length - 1; i >= 0; i--) {
  const message = messages[i] || {};
  if (message.role !== "user") continue;
  if (typeof message.content === "string" && message.content.trim()) {
    inputText = message.content.trim();
    break;
  }
  const parts = Array.isArray(message.parts) ? message.parts : [];
  inputText = parts.map(function(part) {
    return part && part.type === "text" && typeof part.text === "string" ? part.text : "";
  }).join("").trim();
  if (inputText) break;
}
board.setVar("captured-input", inputText);

board.setChannel("planner-messages", [{
  role: "user",
  parts: [{ type: "text", text: board.getVar("captured-input") || "" }]
}]);

const memory = board.getVar("recalled-memory") || "";
const plan = board.getVar("plan") || "";
board.setVar("answer-system-prompt", [
  "你是一个简短、准确的中文语音助手。",
  "请参考下面的长期记忆和执行计划回答用户；长期记忆为空时忽略。",
  "长期记忆：\n" + memory,
  "执行计划：\n" + plan,
  "回答只说一句简短中文，不要提及计划或记忆。"
].join("\n"));
board.setChannel("answer-messages", [{
  role: "user",
  parts: [{ type: "text", text: board.getVar("captured-input") || "" }]
}]);
